export type GroupedGitRefs = {
	locals: RefOption[],
	remotes: RefOption[],
	tags: RefOption[],
};

/**
 *  What the hook subprocess sends us.
 * 
 *  The renderer / Claude Code emit JSON envelopes; the daemon receives
 *  them and lands them here. `payload_json` is the verbatim envelope
 *  minus the routing fields we hoist into typed columns.
 */
export type HookEnvelope = {
	kind: HookKind,
	thread_id: ThreadId | null,
	stream_id: StreamId | null,
	session_id: string | null,
	payload_json: string,
	/**
	 *  Optional client-supplied prompt body for UserPromptSubmit so
	 *  the agent_turn row carries the visible prompt text.
	 */
	prompt: string | null,
};

export type HookEvent = {
	id: HookEventId,
	thread_id: ThreadId | null,
	stream_id: StreamId | null,
	kind: HookKind,
	session_id: string | null,
	/**
	 *  Raw envelope from the hook subprocess, JSON-encoded. The
	 *  pipeline parses this lazily — the persisted form is verbatim.
	 */
	payload_json: string,
	received_at: Timestamp,
};

export type HookEventId = string;

/**
 *  Discriminant for hook events. Matches the kinds Claude Code emits
 *  plus a few oxplow-internal synthetic kinds (Interrupt, AgentBoot).
 */
export type HookKind = 
// Renderer/agent paste, run-command, etc.
"user_prompt_submit" | "pre_tool_use" | "post_tool_use" | "stop" | "subagent_stop" | 
// Synthesized by oxplow when the user hits Ctrl-C / Esc in a pane.
"interrupt" | 
/**
 *  Agent boot sentinel — fires once per session_id when oxplow first
 *  observes traffic for it.
 */
"agent_boot";

/**
 *  Delta between the before- and after-revision import edges for a
 *  single file. `cross_zone_added` is the highlight signal — a new
 *  import that crosses an architectural zone boundary (e.g. `ui`
 *  suddenly reaches into `store`) is the "wrong layer" callout.
 */
export type ImportDelta = {
	path: string,
	added: ZonedImportEdge[],
	removed: ZonedImportEdge[],
	/**
	 *  Subset of `added` whose `from_zone != to_zone` AND `to_zone`
	 *  is known (we never flag external/unresolved targets).
	 */
	cross_zone_added: ZonedImportEdge[],
};

/**
 *  One discovered dependency edge: "this file references this module
 *  in this way at this span."
 */
export type ImportEdge = {
	// Repo-relative path of the importing file (pass-through).
	from_path: string,
	// The exact text of the import declaration as written.
	raw: string,
	/**
	 *  Parsed module identifier — what the author imported. Format
	 *  is language-native: `"std::fs"` for Rust, `"@scope/pkg"` or
	 *  `"./relative"` for JS/TS, `"foo.bar"` for Python/Java,
	 *  `"github.com/foo/bar"` for Go, `"<stdio.h>"` or `"foo.h"` for
	 *  C/C++, `"foo.bar"` for Clojure.
	 */
	module: string,
	// Declaration kind.
	kind: ImportKind,
	// 1-based start line of the import declaration.
	start_line: number,
	// 1-based end line of the import declaration.
	end_line: number,
};

// What kind of dependency declaration produced this edge.
export type ImportKind = 
// Rust `use foo::bar;` / `pub use ...;` / `extern crate foo;`.
"use" | 
/**
 *  JS/TS `import { x } from "foo"` / `import * as x from "foo"`
 *  / `import "foo"`, plus `require("foo")` calls.
 */
"import" | 
// Python `import foo` / `from foo import bar`.
"py_import" | 
// Go `import "foo"` (within a single-or-grouped import decl).
"go_import" | 
// Java `import foo.bar.Baz;` / `import static foo.Bar.baz;`.
"java_import" | 
// C / C++ preprocessor `#include <stdio.h>` / `#include "foo.h"`.
"include" | 
// C++ `using foo::bar;` / `using namespace foo;`.
"using" | 
/**
 *  Clojure `(ns my.ns (:require [foo.bar :as fb]))` or top-level
 *  `(require '[foo.bar :as fb])`.
 */
"clj_require";

export type InstalledLspPackage = {
	name: string,
	version: string,
	language_ids: string[],
	binary: string,
};

/**
 *  Frontend-facing error envelope.
 * 
 *  All command cores return `Result<T, IpcError>`, and the Tauri
 *  `#[tauri::command]` wrappers + the daemon's HTTP routes surface this
 *  same shape. Internal errors from the service layer are converted here
 *  so the JS side never has to reason about Rust-specific error types.
 */
export type IpcError = {
	code: string,
	message: string,
	cause: string | null,
};

/**
 *  Which mode the current process booted in. Managed (and returned by
 *  `get_launch_mode`) so the renderer's `<Root>` can decide between the
 *  launcher screen and the full app shell without guessing.
 */
export type LaunchInfo = {
	// `"launcher"` or `"project"`.
	mode: string,
	// The project dir when `mode == "project"`, else `None`.
	projectDir: string | null,
};

/**
 *  Per-line attribution combining git blame with a local "this line was
 *  last touched in oxplow effort X" overlay. The full TS implementation
 *  could match against snapshot file contents to attribute lines to
 *  efforts; the new schema only persists blob hashes (not full text)
 *  so this Rust port currently surfaces git blame + the BLAME_ZERO_SHA
 *  → "uncommitted" mapping. The task effort attribution arrives
 *  once content-addressed snapshot blob storage lands (see
 *  MIGRATION_REVIEW2 §3 / sharp edge §5).
 */
export type LocalBlameEntry = {
	line: number,
	/**
	 *  "git", "uncommitted", or eventually "local" (once snapshot
	 *  blobs are available).
	 */
	source: string,
	git: BlameLine | null,
};

export type LspServerConfig = {
	languageId: string,
	extensions: string[],
	command: string,
	args?: string[],
};

/**
 *  One row of `list_servers()` — everything the settings page and the
 *  agent need to reason about a configured server.
 */
export type LspServerListing = {
	languageId: string,
	extensions: string[],
	command: string,
	args: string[],
	source: LspServerSource,
	// Mason package name when `source == Installed`.
	packageName: string | null,
	// Installed package version when `source == Installed`.
	version: string | null,
	binaryExists: boolean,
	// Stream ids with a live session for this language.
	runningStreams: string[],
	/**
	 *  `completionProvider.triggerCharacters` from a running session's
	 *  server capabilities, when one exists.
	 */
	completionTriggerCharacters: string[] | null,
};

// Where a server config came from, for the settings UI.
export type LspServerSource = "yaml" | "installed";

export type MenuGroupSnapshot = {
	id: string,
	label: string,
	items: MenuItemSnapshot[],
};

export type MenuItemSnapshot = {
	id: string,
	label: string,
	shortcut: string | null,
	enabled: boolean,
	checked: boolean | null,
	/**
	 *  When present, this item is a nested submenu of these children
	 *  (e.g. File ▸ Open Recent ▸ …) rather than a leaf command.
	 */
	submenu?: MenuItemSnapshot[] | null,
};

// Whether merging `head` into `base` looks safe.
export type MergeReadiness = 
// `head` has no commits beyond `base` — nothing to merge.
"already-integrated" | 
/**
 *  `head` is ahead and no file was touched on both sides since the
 *  merge-base — a merge should apply cleanly.
 */
"clean" | 
/**
 *  `head` is ahead and at least one file was touched on both sides —
 *  a merge will likely conflict (see `overlapping_files`).
 */
"conflict";

export type MoveTaskRequest = {
	id: TaskId,
	// Destination thread, or `None` to move onto the backlog.
	threadId: ThreadId | null,
};

export type NoteId = string;

export type OxplowConfig = {
	/**
	 *  Enabled agent implementations for this project, in priority order.
	 *  The first entry is the default for newly-created threads.
	 */
	agents: AgentKind[],
	/**
	 *  Human-readable project name. Defaults to the basename of the
	 *  project dir when not set in oxplow.yaml.
	 */
	projectName: string,
	// Extra language servers registered on top of the built-ins.
	lspServers: LspServerConfig[],
	// User-supplied text appended verbatim to every agent's system prompt.
	agentPromptAppend: string,
	// File-snapshot retention window in days. 0 disables pruning.
	snapshotRetentionDays: number,
	/**
	 *  Generated paths excluded from fs-watch / snapshot capture /
	 *  code-quality scans. Entries are either a single segment name
	 *  (matched anywhere — e.g. `target` filters every `target/`) or
	 *  a repo-relative path (matched exactly or as a directory
	 *  prefix — e.g. `apps/desktop/dist`, `docs/generated/out.txt`).
	 *  Defaults like `.git`, `node_modules`, `target` apply
	 *  automatically; this list extends them.
	 */
	generated: string[],
	/**
	 *  Maximum blob size for content-addressed snapshotting; larger
	 *  files get a stat-only entry. Default 5 MiB.
	 */
	snapshotMaxFileBytes: number,
	/**
	 *  When true, the UserPromptSubmit hook injects a session-context
	 *  block into every agent prompt.
	 */
	injectSessionContext: boolean,
	// Per-project collection profile (test + coverage instrumentation).
	collection: CollectionConfig,
	/**
	 *  Per-agent launch model overrides, e.g.
	 *  `agentModels: { opencode: "github-copilot/gpt-5-mini" }`.
	 *  Only opencode consumes this today (its `-m provider/model`
	 *  flag); claude/codex launch with their own defaults. Absent
	 *  entries fall back to the built-in constant.
	 */
	agentModels: Partial<{ [key in AgentKind]: string }>,
};

/**
 *  What changed. Variants are deliberately broad — the renderer
 *  refetches the affected bucket on receipt rather than trying to
 *  reconcile diffs from the payload.
 */
export type OxplowEvent = 
/**
 *  Any stream row changed (created, renamed, deleted, panes
 *  updated). Renderer refetches `list_streams`.
 */
{ kind: "streamsChanged" } | 
// The current-stream pointer in `runtime_state` moved.
{ kind: "currentStreamChanged"; streamId: StreamId | null } | 
// Threads on `stream_id` changed (created, status flipped, etc.).
{ kind: "threadsChanged"; streamId: StreamId } | 
// Selected-thread pointer for `stream_id` moved.
{ kind: "selectedThreadChanged"; streamId: StreamId; threadId: ThreadId | null } | 
// tasks on `thread_id` (or backlog if `thread_id` is None).
{ kind: "tasksChanged"; threadId: ThreadId | null } | 
// A note was added or removed against an item or thread.
{ kind: "workNotesChanged"; itemId: TaskId | null; threadId: ThreadId | null } | 
/**
 *  A comment (or one of its messages) changed on `target_kind` /
 *  `target_id` within `stream_id`. Renderer refetches the affected
 *  page's comments + the Comments inbox.
 */
{ kind: "commentsChanged"; streamId: StreamId; targetKind: string; targetId: string } | 
/**
 *  A wiki page's backing file changed on disk (creation, body
 *  update, deletion). `slug` is the file stem — subscribers
 *  (e.g. `WikiPageTab`) filter by their own slug so an unrelated
 *  edit doesn't trigger a refresh.
 */
{ kind: "wikiPagesChanged"; slug: string } | 
// Followups for a thread.
{ kind: "followupsChanged"; threadId: ThreadId } | 
// Background task progress.
{ kind: "backgroundTasksChanged" } | 
/**
 *  The set of known language servers changed (Mason package
 *  installed or removed). Renderer refetches `list_lsp_servers`.
 */
{ kind: "lspServersChanged" } | 
// A new hook event landed; renderer refreshes the hook log.
{ kind: "hookEventsChanged" } | 
/**
 *  Per-thread per-pane agent status changed. `state` carries the
 *  derived status so the renderer can update without a refetch
 *  round-trip — sources that don't have it pre-derived (e.g.
 *  PreToolUse/PostToolUse, where the renderer used to refetch and
 *  re-derive) compute it inline before emitting.
 */
{ kind: "agentStatusChanged"; threadId: ThreadId; paneTarget: string; state: AgentStatusState } | 
// agent_turn opened or closed.
{ kind: "agentTurnsChanged"; threadId: ThreadId } | 
/**
 *  The stall watchdog noticed `thread_id` has in_progress tasks
 *  but its agent has not been running for longer than the alert
 *  threshold — the queue is silently stalled. Emitted once per
 *  stall episode (re-armed when the agent runs again or the
 *  in_progress bucket empties). Renderer surfaces a toast.
 */
{ kind: "agentStallAlert"; threadId: ThreadId; inProgressCount: number; waitingMs: number } | 
/**
 *  A page visit was recorded (rail history, recently-finished, etc.).
 *  Coarse — renderer refetches whatever view it cares about.
 */
{ kind: "pageVisitChanged" } | 
/**
 *  A usage event was recorded. The renderer's filtering uses
 *  `usage_kind` to scope refetches (wiki vs editor-file vs
 *  task, etc.).
 */
{ kind: "usageRecorded"; usageKind: string; key: string; streamId: StreamId | null; threadId: ThreadId | null } | 
/**
 *  A file snapshot landed in the snapshot store. Driven by the
 *  background snapshot capture loop or an explicit task event.
 */
{ kind: "fileSnapshotCreated"; streamId: StreamId | null; snapshotId: number; source: SnapshotSourceKind; effortId: string | null; threadId: ThreadId | null } | 
/**
 *  A batched flush of N file snapshots landed under one parent.
 *  Emitted instead of N per-file `FileSnapshotCreated` events when
 *  `request_snapshot` drains many paths at once (startup sweep,
 *  branch switch). Renderer treats it the same as the per-file
 *  variant — fire-and-forget refetch — so a 34k-file batch causes
 *  one refetch, not 34k.
 */
{ kind: "fileSnapshotsBatchCreated"; streamId: StreamId | null; snapshotId: number; fileCount: number; source: SnapshotSourceKind; effortId: string | null; threadId: ThreadId | null } | 
/**
 *  Effort-scoped collection observations changed for `effort_id`
 *  (a test-run or diff-coverage row landed). The renderer refetches
 *  the effort's observation list. See `.context/collection.md`.
 */
{ kind: "effortObservationsChanged"; threadId: ThreadId; effortId: string } | 
/**
 *  A persisted agent nudge landed (report-less-run / commit-hygiene).
 *  The renderer refetches the effort's (or thread's) nudge list. See
 *  `.context/agent-model.md` (Nudge persistence).
 */
{ kind: "agentNudgesChanged"; threadId: ThreadId; effortId: string | null } | 
/**
 *  A per-turn agent token-usage row landed (parsed on Stop from the
 *  hook transcript). The renderer refetches the effort's usage list +
 *  the thread's running total. `effort_id` is absent when the Stop had
 *  no open effort. See `.context/agent-model.md` (Token usage capture).
 */
{ kind: "agentTokenUsageChanged"; threadId: ThreadId; effortId: string | null } | 
/**
 *  `oxplow.yaml` was reloaded from disk (external edit, e.g. the agent
 *  running `/oxplow:configure`). The in-memory config has been swapped;
 *  the renderer refetches `get_config`.
 */
{ kind: "configChanged" } | 
/**
 *  A code-quality scan transitioned states (started / completed /
 *  failed). The renderer refreshes scan + finding lists on receipt.
 */
{ kind: "codeQualityScanned"; streamId: StreamId | null; scanId: number; tool: string; scope: string; phase: CodeQualityScanPhase } | 
/**
 *  `.git` directory appeared/disappeared at the project root —
 *  "is this a git workspace" flipped. Renderer hides/restores the
 *  git-aware UI on receipt.
 */
{ kind: "workspaceContextChanged"; gitEnabled: boolean } | 
/**
 *  A worktree file changed on disk. Renderer-wide: file tree, quick
 *  open, project panel, git dashboard, uncommitted changes view all
 *  refresh in response.
 */
{ kind: "workspaceChanged"; streamId: StreamId; changeKind: WorkspaceChangeKind; path: string } | 
/**
 *  A ref under `.git/refs/` changed. Drives history, branch list,
 *  and ahead/behind refreshes. Coarse per stream.
 */
{ kind: "gitRefsChanged"; streamId: StreamId } | 
/**
 *  A non-primary stream's backing worktree was deleted out from
 *  under us (externally `rm -rf`'d, `git worktree remove`'d, etc.).
 *  The runtime has already archived the stream by the time this
 *  fires; the renderer surfaces a toast so the user knows why the
 *  rail row vanished. `title` carries the archived stream's display
 *  name.
 */
{ kind: "streamOrphaned"; streamId: StreamId; title: string };

